import{createBoardingApproach,sampleBoardingApproach}from'../transport/boarding-approach.js';
import * as THREE from 'three';
import {createBoatView,BOAT} from './boat-view.js';
import {createBoatCamera} from './camera.js';
import {createBoatWake} from './wake.js';
import {sampleBoarding,sampleBoatExit,sampleVessel,boatEase} from './motion.js';
